import{_ as e,c as o,o as i,a0 as n}from"./chunks/framework.oTSD2LDJ.js";const u=JSON.parse('{"title":"Components Overview","description":"","frontmatter":{"title":"Components Overview","layout":"doc","editLink":true},"headers":[],"relativePath":"en/components-wiki/overview.md","filePath":"en/components-wiki/overview.md"}'),r={name:"en/components-wiki/overview.md"};function a(l,t,s,d,c,h){return i(),o("div",null,t[0]||(t[0]=[n('<h1 id="components-overview" tabindex="-1">Components Overview <a class="header-anchor" href="#components-overview" aria-label="Permalink to &quot;Components Overview&quot;">​</a></h1><p>Welcome to Uniquenium! This guide will introduce you to the core features and basic operation methods.</p><h2 id="interface-introduction" tabindex="-1">Interface Introduction <a class="header-anchor" href="#interface-introduction" aria-label="Permalink to &quot;Interface Introduction&quot;">​</a></h2><p>The main interface of Uniquenium consists of the following parts:</p><h3 id="tray-area" tabindex="-1">Tray Area <a class="header-anchor" href="#tray-area" aria-label="Permalink to &quot;Tray Area&quot;">​</a></h3><p>After launching, the program minimizes to the system tray area (bottom-right of the taskbar) by default:</p><ul><li><strong>Left-click</strong>: Show/hide the main panel</li><li><strong>Right-click</strong>: Open the tray menu, including: <ul><li>Show main panel</li><li>Page management</li><li>Settings</li><li>Plugin management</li><li>Exit program</li></ul></li></ul><h3 id="main-panel" tabindex="-1">Main Panel <a class="header-anchor" href="#main-panel" aria-label="Permalink to &quot;Main Panel&quot;">​</a></h3><p>The main panel is the core operation area of Uniquenium, divided into:</p><ol><li><strong>Left Navigation Bar</strong>: Page list, create/delete/switch pages</li><li><strong>Middle Workspace</strong>: Page canvas, where components are displayed and edited</li><li><strong>Right Property Panel</strong>: Shows property editing options when a component is selected (edit mode)</li></ol><h3 id="edit-mode-vs-browse-mode" tabindex="-1">Edit Mode vs. Browse Mode <a class="header-anchor" href="#edit-mode-vs-browse-mode" aria-label="Permalink to &quot;Edit Mode vs. Browse Mode&quot;">​</a></h3><p>Uniquenium has two operating modes:</p><ul><li><strong>Edit Mode</strong>: Can add, delete, drag components, adjust properties</li><li><strong>Browse Mode</strong>: Components display normally but cannot be modified (daily use state)</li></ul><p>Switch via the &quot;Edit/Browse&quot; toggle button in the top toolbar, or press <code>Ctrl + E</code>.</p><hr><h2 id="creating-pages" tabindex="-1">Creating Pages <a class="header-anchor" href="#creating-pages" aria-label="Permalink to &quot;Creating Pages&quot;">​</a></h2><p>Pages are containers for Uniquenium to organize components. You can create multiple independent pages, for example:</p><ul><li>Main panel: put clock, weather, quick launch</li><li>Monitoring panel: put CPU/memory/network monitoring charts</li><li>Work panel: put to-do items, notes</li></ul><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Open the main panel, make sure you are in <strong>Edit Mode</strong></li><li>Click the <strong>&quot;+ New Page&quot;</strong> button at the top of the left navigation bar</li><li>Enter the page name in the dialog that pops up (e.g., &quot;My Home&quot;)</li><li>Select the page style: <ul><li><strong>Normal Panel</strong>: Fixed-size window panel</li><li><strong>Full-screen Overlay</strong>: Translucent layer covering the entire screen</li><li><strong>Frameless Panel</strong>: Freely resizable</li></ul></li><li>Click &quot;OK&quot; to complete creation</li></ol><h3 id="page-management" tabindex="-1">Page Management <a class="header-anchor" href="#page-management" aria-label="Permalink to &quot;Page Management&quot;">​</a></h3><ul><li><strong>Switch Page</strong>: Click the page name in the left navigation bar</li><li><strong>Rename Page</strong>: Right-click page → Rename</li><li><strong>Delete Page</strong>: Right-click page → Delete (warning: all components in the page will also be deleted)</li><li><strong>Copy Page</strong>: Right-click page → Copy as New Page</li><li><strong>Export Template</strong>: Right-click page → Export as Template (share or backup)</li><li><strong>Page Sorting</strong>: Drag directly in the navigation bar to adjust order</li></ul><hr><h2 id="adding-components" tabindex="-1">Adding Components <a class="header-anchor" href="#adding-components" aria-label="Permalink to &quot;Adding Components&quot;">​</a></h2><p>Uniquenium provides a variety of built-in components, and more can be extended through the plugin system.</p><h3 id="addition-steps" tabindex="-1">Addition Steps <a class="header-anchor" href="#addition-steps" aria-label="Permalink to &quot;Addition Steps&quot;">​</a></h3><ol><li>Make sure you are in <strong>Edit Mode</strong></li><li>Click the <strong>&quot;Add Component&quot;</strong> button in the toolbar (or press <code>Ctrl + Shift + A</code>)</li><li>In the component selection window, select the component type from the left category: <ul><li><strong>Basic</strong>: Text, Image, Button, Icon</li><li><strong>Input</strong>: Text Field, CheckBox, Dropdown Selection</li><li><strong>Container</strong>: Frame, Tab</li><li><strong>Display</strong>: Chart, Progress Bar, Tooltip</li><li><strong>Window</strong>: Dialog, Message Box</li><li><strong>Custom</strong>: Components provided by plugins</li></ul></li><li>Click or drag the component to the workspace to add it</li></ol><h3 id="recommended-components" tabindex="-1">Recommended Components <a class="header-anchor" href="#recommended-components" aria-label="Permalink to &quot;Recommended Components&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>Purpose</th><th>Example Scenario</th></tr></thead><tbody><tr><td>UniDeskText</td><td>Display text</td><td>Clock title, note content</td></tr><tr><td>UniDeskImage</td><td>Display images</td><td>Avatar, photo wall, Logo</td></tr><tr><td>UniDeskButton</td><td>Click button</td><td>Quick launch, function toggle</td></tr><tr><td>UniDeskFrame</td><td>Group container</td><td>Group multiple components together</td></tr><tr><td>UniDeskChart</td><td>Data chart</td><td>CPU/memory usage monitoring</td></tr><tr><td>UniDeskTextField</td><td>Text input</td><td>To-do input field</td></tr><tr><td>UniDeskIcon</td><td>Icon display</td><td>Function icon, status indicator</td></tr></tbody></table><hr><h2 id="component-property-editing" tabindex="-1">Component Property Editing <a class="header-anchor" href="#component-property-editing" aria-label="Permalink to &quot;Component Property Editing&quot;">​</a></h2><p>After selecting a component, the right property panel displays the editable properties for that component.</p><h3 id="basic-operations" tabindex="-1">Basic Operations <a class="header-anchor" href="#basic-operations" aria-label="Permalink to &quot;Basic Operations&quot;">​</a></h3><h4 id="select-component" tabindex="-1">Select Component <a class="header-anchor" href="#select-component" aria-label="Permalink to &quot;Select Component&quot;">​</a></h4><ul><li><strong>Click</strong> the component in the workspace to select it (blue border displayed)</li><li><strong>Multi-select</strong>: Hold <code>Shift</code> and click sequentially, or drag to select multiple components</li><li><strong>Select All</strong>: <code>Ctrl + A</code></li><li><strong>Deselect</strong>: Click blank area or press <code>Esc</code></li></ul><h4 id="move-resize" tabindex="-1">Move &amp; Resize <a class="header-anchor" href="#move-resize" aria-label="Permalink to &quot;Move &amp; Resize&quot;">​</a></h4><ul><li><strong>Move</strong>: Drag the component directly to the target position</li><li><strong>Precise Move</strong>: Use arrow keys to fine-tune (1 pixel), hold <code>Shift</code> + arrow keys to move 10 pixels at a time</li><li><strong>Resize</strong>: Drag edge or corner control points after selecting the component</li><li><strong>Keep Proportion</strong>: Hold <code>Shift</code> and drag corner control point</li></ul><h4 id="copy-delete" tabindex="-1">Copy &amp; Delete <a class="header-anchor" href="#copy-delete" aria-label="Permalink to &quot;Copy &amp; Delete&quot;">​</a></h4><ul><li><strong>Copy</strong>: After selecting, press <code>Ctrl + C</code>, then <code>Ctrl + V</code> to paste; or right-click → Copy</li><li><strong>Cut</strong>: <code>Ctrl + X</code></li><li><strong>Delete</strong>: Press <code>Delete</code>; or right-click → Delete</li></ul><h3 id="common-properties" tabindex="-1">Common Properties <a class="header-anchor" href="#common-properties" aria-label="Permalink to &quot;Common Properties&quot;">​</a></h3><p>Common properties for all components:</p><table tabindex="0"><thead><tr><th>Property</th><th>Description</th><th>Example Value</th></tr></thead><tbody><tr><td>X / Y</td><td>Component top-left coordinate (pixels)</td><td>X: 100, Y: 50</td></tr><tr><td>Width / Height</td><td>Component size (pixels)</td><td>W: 200, H: 100</td></tr><tr><td>Opacity</td><td>0 (fully transparent) ~ 1 (fully opaque)</td><td>0.85</td></tr><tr><td>Visibility</td><td>Whether to display the component</td><td>true / false</td></tr><tr><td>Z-Order</td><td>Component stacking order, larger values go on top</td><td>0, 1, 2...</td></tr><tr><td>Component ID</td><td>Unique identifier for script references</td><td>myButton_001</td></tr></tbody></table><h3 id="layer-adjustment" tabindex="-1">Layer Adjustment <a class="header-anchor" href="#layer-adjustment" aria-label="Permalink to &quot;Layer Adjustment&quot;">​</a></h3><p>The component&#39;s layer (Z-axis) determines which one displays on top when overlapping:</p><ul><li>Right-click component → <strong>Bring to Front</strong> (set Z to maximum)</li><li>Right-click component → <strong>Send to Back</strong> (set Z to minimum)</li><li>Right-click component → <strong>Move Up One Layer</strong> (Z +1)</li><li>Right-click component → <strong>Move Down One Layer</strong> (Z -1)</li><li>Drag directly in the left &quot;Component Tree&quot; panel to adjust order</li></ul><h3 id="alignment-distribution" tabindex="-1">Alignment &amp; Distribution <a class="header-anchor" href="#alignment-distribution" aria-label="Permalink to &quot;Alignment &amp; Distribution&quot;">​</a></h3><p>After selecting multiple components, use the toolbar alignment buttons:</p><ul><li>Left align / Right align / Vertical center</li><li>Top align / Bottom align / Horizontal center</li><li>Horizontal equal spacing / Vertical equal spacing</li><li>Equal width / Equal height / Equal size</li></ul><hr><h2 id="shortcut-settings" tabindex="-1">Shortcut Settings <a class="header-anchor" href="#shortcut-settings" aria-label="Permalink to &quot;Shortcut Settings&quot;">​</a></h2><p>Properly using shortcuts can greatly improve operational efficiency. Uniquenium supports rich global hotkey binding.</p><h3 id="default-shortcuts" tabindex="-1">Default Shortcuts <a class="header-anchor" href="#default-shortcuts" aria-label="Permalink to &quot;Default Shortcuts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Shortcut</th><th>Function</th></tr></thead><tbody><tr><td><code>Ctrl + Alt + U</code></td><td>Show/hide main panel</td></tr><tr><td><code>Ctrl + Alt + S</code></td><td>Open settings window</td></tr><tr><td><code>Ctrl + E</code></td><td>Toggle edit/browse mode</td></tr><tr><td><code>Ctrl + Shift + A</code></td><td>Add new component</td></tr><tr><td><code>Ctrl + N</code></td><td>Create new page</td></tr><tr><td><code>Ctrl + S</code></td><td>Save current page</td></tr><tr><td><code>Ctrl + Z</code></td><td>Undo previous action</td></tr><tr><td><code>Ctrl + Shift + Z</code></td><td>Redo action</td></tr><tr><td><code>Delete</code></td><td>Delete selected component</td></tr><tr><td><code>Ctrl + D</code></td><td>Quickly copy selected component</td></tr></tbody></table><h3 id="custom-shortcuts" tabindex="-1">Custom Shortcuts <a class="header-anchor" href="#custom-shortcuts" aria-label="Permalink to &quot;Custom Shortcuts&quot;">​</a></h3><ol><li>Open the <strong>Settings</strong> → <strong>Shortcuts</strong> tab</li><li>Find the function to modify, click the shortcut input box</li><li>Press the new key combination you want (e.g., <code>Ctrl + Alt + H</code>)</li><li>If &quot;already in use&quot; is prompted, choose another combination</li><li>Click &quot;Apply&quot; to save settings</li></ol><div class="tip custom-block"><p class="custom-block-title">Tip</p><ul><li>Recommended to use <code>Ctrl + Alt + letter</code> or <code>Win + Shift + letter</code> as global hotkeys, with fewer conflicts</li><li>Numeric keypad keys can also be bound, suitable for frequently used functions</li></ul></div><h3 id="shortcut-conflict-handling" tabindex="-1">Shortcut Conflict Handling <a class="header-anchor" href="#shortcut-conflict-handling" aria-label="Permalink to &quot;Shortcut Conflict Handling&quot;">​</a></h3><p>If the set shortcut doesn&#39;t work:</p><ol><li>Check if occupied by other software (QQ, WeChat, input methods, browsers commonly use <code>Alt + letter</code>)</li><li>Try running Uniquenium as <strong>administrator</strong> (some system hotkeys require higher permissions)</li><li>Change to a less commonly used combination, such as <code>Ctrl + Shift + F12</code></li></ol><hr><h2 id="theme-switching" tabindex="-1">Theme Switching <a class="header-anchor" href="#theme-switching" aria-label="Permalink to &quot;Theme Switching&quot;">​</a></h2><p>Uniquenium supports three theme modes to perfectly match your Windows appearance.</p><h3 id="switching-method" tabindex="-1">Switching Method <a class="header-anchor" href="#switching-method" aria-label="Permalink to &quot;Switching Method&quot;">​</a></h3><ol><li>Open the <strong>Settings</strong> → <strong>Appearance</strong> tab</li><li>Select in &quot;Theme Mode&quot;: <ul><li><strong>Follow System</strong> (recommended): Auto-sync Windows dark/light settings</li><li><strong>Light Mode</strong>: Fresh and bright white interface</li><li><strong>Dark Mode</strong>: Eye-friendly and power-saving black interface</li></ul></li><li>Click &quot;Apply&quot; to take effect immediately, no restart needed</li></ol><h3 id="theme-color-settings" tabindex="-1">Theme Color Settings <a class="header-anchor" href="#theme-color-settings" aria-label="Permalink to &quot;Theme Color Settings&quot;">​</a></h3><p>In addition to dark/light mode, you can also customize the accent color (primary color):</p><ul><li>Click &quot;Theme Color&quot; in the &quot;Appearance&quot; tab</li><li>Select a preset color, or click &quot;Custom Color&quot; to use the color picker</li><li>All buttons, highlights, and selection frames will automatically use this color</li></ul><h3 id="acrylic-effect" tabindex="-1">Acrylic Effect <a class="header-anchor" href="#acrylic-effect" aria-label="Permalink to &quot;Acrylic Effect&quot;">​</a></h3><p>The UniDesk control library supports <strong>Acrylic</strong> blur effects (similar to Windows 11&#39;s Mica material):</p><ul><li><strong>Enable location</strong>: Settings → Appearance → Enable Acrylic Effect</li><li><strong>Blur intensity</strong>: Adjust slider, higher values make the background more blurry (0-100)</li><li><strong>Color concentration</strong>: Adjust the opacity of the panel color</li></ul><div class="warning custom-block"><p class="custom-block-title">Performance Note</p><p>The acrylic effect consumes GPU resources. If your computer has lower specs or uses battery power, it is recommended to disable it to save power.</p></div><hr><h2 id="more-features" tabindex="-1">More Features <a class="header-anchor" href="#more-features" aria-label="Permalink to &quot;More Features&quot;">​</a></h2><ul><li><strong>Custom Wallpapers</strong>: Settings → Appearance → Wallpaper, supports local images, multi-image carousel, network APIs</li><li><strong>Custom Cursors</strong>: Refer to <a href="/en/custom-developing/cursor-style">Custom Cursor Styles</a></li><li><strong>Template System</strong>: Refer to <a href="/en/custom-developing/template">Template Usage Guide</a></li><li><strong>Plugin Extension</strong>: Refer to <a href="/en/custom-developing/plugin">Plugin Development Guide</a></li><li><strong>Control Development</strong>: Refer to <a href="/en/controls-reference/overview">UniDesk Control Library Overview</a></li></ul><p>Having issues? Check the <a href="/en/faq">FAQ</a> or <a href="https://github.com/Uniquenium/Uniquenium/issues" target="_blank" rel="noreferrer">Submit an Issue</a>.</p>',75)]))}const g=e(r,[["render",a]]);export{u as __pageData,g as default};
